INSERT INTO public.legal_documents (id, title, title_ne, doc_type, category, enactment_date_bs, status, description, official_source_url) VALUES
('20000000-0000-0000-0000-000000000001', 'Civil Service Act, 2049', 'निजामती सेवा ऐन, २०४९', 'ACT', 'निजामती प्रशासन तथा सेवा सर्त', '२०५०/०२/०४', 'ACTIVE', 'निजामती सेवालाई सक्षम, सुदृढ, सेवामूलक र उत्तरदायी बनाउन बनेको मूल ऐन।', 'https://lawcommission.gov.np'),
('20000000-0000-0000-0000-000000000002', 'Public Procurement Act, 2063', 'सार्वजनिक खरिद ऐन, २०६३', 'ACT', 'सार्वजनिक खरिद तथा वित्तीय व्यवस्थापन', '२०६३/०९/३०', 'ACTIVE', 'सार्वजनिक खरिद प्रक्रियालाई पारदर्शी, वस्तुनिष्ठ, विश्वसनीय र मितव्ययी बनाउन बनेको ऐन।', 'https://lawcommission.gov.np'),
('20000000-0000-0000-0000-000000000003', 'Good Governance Act, 2064', 'सुशासन (व्यवस्थापन तथा सञ्चालन) ऐन, २०६४', 'ACT', 'सुशासन तथा सेवा प्रवाह', '२०६४/१०/२३', 'ACTIVE', 'मुलुकको सार्वजनिक प्रशासनलाई जनमुखी, जवाफदेही, पारदर्शी र परिणाममुखी बनाउन जारी भएको ऐन।', 'https://lawcommission.gov.np')
INSERT INTO public.legal_sections (id, document_id, chapter_no, chapter_title_ne, section_no, title_ne, content_ne, simple_explanation_ne) VALUES
('30000000-0000-0000-0000-000000000001', '20000000-0000-0000-0000-000000000001', 'परिच्छेद-३', 'पदपूर्ति', 'दफा ७', 'पदपूर्ति सम्बन्धी व्यवस्था', 'निजामती सेवाका रिक्त पदहरूको पूर्ति लोक सेवा आयोगद्वारा लिइने खुला प्रतियोगितात्मक परीक्षा तथा आन्तरिक बढुवाद्वारा गरिनेछ। आरक्षण सम्बन्धी ४५% कोटालाई महिला, आदिवासी जनजाति, मधेसी, दलित, अपाङ्गता भएका र पिछडिएको क्षेत्रमा विभाजन गरिएको छ।', 'सरकारी सेवाका पदहरू लोक सेवा परीक्षा तथा बढुवाबाट भरिन्छन् जसमा ४५% समावेशी समूहका लागि छुट्याइएको हुन्छ।'),
('30000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000001', 'परिच्छेद-४', 'सरुवा र पदस्थापन', 'दफा १८', 'कर्मचारीको सरुवा सम्बन्धी व्यवस्था', 'निजामती कर्मचारीलाई सामान्यतया वर्षमा एकपटक तोकिएको समय तालिका अनुसार सरुवा गरिनेछ। भौगोलिक क्षेत्र (क, ख, ग, घ वर्ग) को अनुभव र कार्यसम्पादन मूल्याङ्कनलाई सरुवाको आधार बनाइनेछ। अवधि नपुगी विशेष परिस्थिति बाहेक सरुवा गर्न पाइने छैन।', 'नियमित सरुवा भदौ महिनाभित्र र तोकिएको भौगोलिक क्षेत्रमा कार्य अवधि पूरा भएपछि मात्र कानुनबमोजिम गरिन्छ।'),
('30000000-0000-0000-0000-000000000003', '20000000-0000-0000-0000-000000000001', 'परिच्छेद-७', 'सेवाको सुरक्षा र अवकाश', 'दफा ३३', 'अनिवार्य अवकाशको उमेर हद', 'निजामती कर्मचारीले अन्ठाउन्न (५८) वर्षको उमेर पूरा भएपछि निजामती सेवाबाट स्वतः अनिवार्य अवकाश पाउनेछ। निजामती किताबखानामा दर्ता भएको जन्ममिति वा नागरिकता प्रमाणपत्रमा उल्लेखित मितिमध्ये जुन पहिले आउँछ सोही आधार मानिनेछ।', 'निजामती कर्मचारीको अनिवार्य अवकाश उमेर ५८ वर्ष हो, जसमा सिटरोल र नागरिकताको सुरु मिति जे जेठो छ सोही गणना हुन्छ।'),
('30000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000002', 'परिच्छेद-२', 'खरिद प्रक्रिया', 'दफा ८', 'खरिदको गुरुयोजना र वार्षिक योजना', 'सार्वजनिक निकायले आर्थिक वर्ष सुरु हुनु अगावै एक वर्षको वार्षिक खरिद योजना र बहुवर्षीय योजना भए खरिद गुरुयोजना तयार गरी स्वीकृत गराउनु पर्नेछ। योजना बिना कुनै पनि सार्वजनिक खरिद प्रक्रिया अगाडि बढाउन पाइने छैन।', 'कुनै पनि कार्यालयले खरिद गर्नुअघि अनिवार्य वार्षिक खरिद योजना तयार पारी स्वीकृत गराउनै पर्छ।'),
('30000000-0000-0000-0000-000000000005', '20000000-0000-0000-0000-000000000002', 'परिच्छेद-४', 'खरिदका विधिहरू', 'दफा ४१', 'सोझै खरिद गर्न सकिने विशेष अवस्था', 'तोकिएको रकमको सीमा (रु. ५ लाख सम्म मालसामान वा परामर्श) सम्म सिलबन्दी दरभाउपत्र वा सोझै खरिद गर्न सकिन्छ। विपद्, आकस्मिक परिस्थिति वा उत्पादक एउटा मात्र भएको अवस्थामा कानुनले तोकेका आधार खोली सोझै खरिद गर्न सकिन्छ।', 'नियमित रूपमा ५ लाखसम्म सोझै खरिद गर्न सकिन्छ, विपद् वा आपतकालीन अवस्थामा विशेष निर्णय गरी सोझै खरिदको बाटो अपनाउन पाइन्छ।')
INSERT INTO public.government_circulars (id, title_ne, issuing_authority, circular_no, issued_date_bs, subject_category, priority, summary_ne, official_link) VALUES
('40000000-0000-0000-0000-000000000001', 'आ.व. २०८१/८२ को कार्यसम्पादन सम्झौता र प्रगति प्रतिवेदन सम्बन्धमा', 'प्रधानमन्त्री तथा मन्त्रिपरिषद्को कार्यालय', 'प.म.का/०८१-२४', '२०८१/०५/१५', 'सुशासन तथा अनुगमन', 'VERY_URGENT', 'सबै मन्त्रालय, आयोग तथा निकायहरूले आ-आफ्नो मातहतका कर्मचारीसँग कार्यसम्पादन सम्झौता गरी त्रैमासिक प्रगति विवरण अनलाइन प्रणालीमा प्रविष्ट गर्नुपर्ने परिपत्र।', 'https://opmcm.gov.np'),
('40000000-0000-0000-0000-000000000002', 'कर्मचारीको व्यक्तिगत विवरण (PIS) अद्यावधिक गर्ने सम्बन्धमा', 'सङ्घीय मामिला तथा सामान्य प्रशासन मन्त्रालय', 'स.मा.सा.प्र./०८१-११', '२०८१/०६/०२', 'कर्मचारी प्रशासन', 'URGENT', 'राष्ट्रिय किताबखाना (निजामती) मा आफ्नो वैयक्तिक विवरण फाराम (सिटरोल) नयाँ शैक्षिक योग्यता तथा तालिम थप गरी अनिवार्य रुजु गराउनुहुन।', 'https://mofaga.gov.np'),
('40000000-0000-0000-0000-000000000003', 'चालु आर्थिक वर्षको बजेट खर्चमा मितव्ययिता कायम गर्ने मापदण्ड', 'अर्थ मन्त्रालय', 'अ.म./०८१-०९', '२०८१/०४/०८', 'बजेट तथा वित्तीय प्रशासन', 'NORMAL', 'इन्धन, बैठक भत्ता, नयाँ सवारी साधन खरिद तथा वैदेशिक भ्रमणमा नियन्त्रण गरी वित्तीय अनुशासन पालना गर्ने सम्बन्धी निर्देशिका।', 'https://mof.gov.np')
